// Clean the two form fields and plan the search. The text is added to
// search queries, so it must stay plain words: no quotes, operators or site:
// filters that could steer them.
const form = $input.first().json;
const raw = String(form.name || '');
const clean = (s) => String(s || '')
  .replace(/\b\w+:\S+/g, ' ')
  .replace(/(^|\s)!\w+/g, ' ')
  .replace(/["'()]/g, ' ')
  .replace(/(^|\s)[-+]\S*/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 60);

const name = clean(form.name);
const kind = clean(form.kind);
// Letters and digits only, lower case: how the product is recognised later. A name in a script
// the Latin steps do not know (Cyrillic, Chinese, Arabic) keeps its own letters.
const alnum = (s) => String(s).toLowerCase().split('+').join('plus').split('#').join('sharp').split('').filter((c) => (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')).join('');
const key = alnum(name) || (/[\p{L}\p{N}]/u.test(name) ? name.toLowerCase().split(' ').join('') : '');
// Words that do not identify a product: a tool called "Microsoft Teams" is
// "teams" to nobody, and its alternatives may well contain "Microsoft".
const GENERIC = ['com', 'app', 'io', 'net', 'org', 'ai', 'the', 'docs', 'code', 'studio', 'pro', 'plus', 'suite', 'office', 'cloud', 'web', 'team', 'teams', 'work', 'one',
  'microsoft', 'google', 'apple', 'adobe', 'amazon', 'zoho', 'atlassian', 'salesforce', 'oracle', 'ibm', 'meta', 'sap', 'aws'];
const words = name.toLowerCase().split(' ').join('.').split('.').map(alnum).filter(Boolean);
const vendorFirst = words.length > 1 && GENERIC.includes(words[0]);
const tokens = vendorFirst ? [] : words.filter((t) => t.length >= 3 && !GENERIC.includes(t)).slice(0, 1);
const ownLabels = vendorFirst ? [words[0]] : tokens;

let problem = '';
if (raw.includes('://') || raw.includes('/') || raw.trim().toLowerCase().startsWith('www.')) problem = 'Type the name of the product, not a web address.';
else if (key.length < 2) problem = 'Type the name of a software product, for example Notion or Trello.';

const base = { ok: !problem, problem, name, kind, key, tokens, ownLabels, today: $now.toFormat('yyyy-MM-dd'), year: Number($now.toFormat('yyyy')) };
if (problem) return [{ json: base }];

return [{ json: Object.assign({}, base, { query: (name + ' alternatives ' + kind).trim() }) }];

// Turn the search results into numbered sources, S1, S2..., in code, so the
// model can only point at a source that exists. A result counts only if its
// page was actually read (a search snippet can be cut short or missing from
// the page it links to), is a list of alternatives, and is not the product's
// own site; each site gives one page, and each source is one vote. Page text
// is untrusted and is fenced with a per-run nonce.
const req = $('Check the request').first().json;
const results = $input.all().map((i) => i.json);

const failure = results.find((r) => r.error);
const blocked = !!failure && /challenge|bot-detection|back-off|not sent|rate.?limit|too many requests|access denied|unusual search|status code (403|429)/i.test(String(failure.error));

const dropped = [];
const drop = (p, reason) => dropped.push({ title: p.title, host: p.host, reason });

// Text that is a page's furniture rather than its content passes a length
// check, so it is caught by what it says.
const WALL = /enable javascript|accept (all )?cookies|cookie (policy|settings|consent)|subscribe to (continue|read)|access denied|are you a robot|verify you are (a )?human|sign in to continue|log in to continue/i;

// Host and registrable domain by plain string steps: the Code sandbox has no
// URL class.
const hostOf = (url) => {
  const s = String(url);
  const at = s.indexOf('://');
  if (at === -1) return '';
  let rest = s.slice(at + 3);
  const end = rest.search(/[\/?#]/);
  if (end !== -1) rest = rest.slice(0, end);
  const user = rest.lastIndexOf('@');
  if (user !== -1) rest = rest.slice(user + 1);
  const colon = rest.lastIndexOf(':');
  if (colon !== -1 && rest.indexOf(']') === -1) rest = rest.slice(0, colon);
  return rest.toLowerCase().replace(/^www\./, '');
};
const SECOND = ['co', 'com', 'org', 'net', 'ac', 'gov', 'edu', 'or', 'ne', 'go'];
// Sites where every author has a sub-domain: their sub-domain is the site.
const PLATFORMS = ['medium.com', 'substack.com', 'blogspot.com', 'wordpress.com', 'github.io', 'hashnode.dev', 'notion.site'];
const registrable = (host) => {
  const p = host.split('.');
  if (p.length <= 2) return host;
  const last2 = p.slice(-2).join('.');
  if (PLATFORMS.includes(last2)) return p.slice(-3).join('.');
  if (p[p.length - 1].length === 2 && SECOND.includes(p[p.length - 2])) return p.slice(-3).join('.');
  return last2;
};

// 1. Pages that were read. The same address found twice is one page.
const seen = new Map();
let found = 0;
for (const r of results) {
  if (!r.url || r.error) continue;
  found += 1;
  const content = typeof r.pageContent === 'string' ? r.pageContent.replace(/[\u00AD\u200B-\u200F\u2060\uFEFF]/g, '').trim() : '';
  const garbled = (content.match(/�/g) || []).length > content.length * 0.01;
  const host = hostOf(r.url);
  const page = { title: String(r.pageTitle || r.title || host).slice(0, 200), url: r.url, host, domain: registrable(host), published: r.pagePublished || null, truncated: !!r.pageContentTruncated, text: content };
  if (!host) continue;
  if (r.pageContentError || content.length < 600 || garbled || WALL.test(content.slice(0, 800))) {
    drop(page, r.pageContentError ? 'the page could not be read (' + String(r.pageContentError).slice(0, 60) + ')' : 'no readable article text');
    continue;
  }
  const u = String(r.url).toLowerCase().split('#')[0];
  const at = u.indexOf(host);
  const key = host + (at === -1 ? u : u.slice(at + host.length)).replace(/\/+$/, '');
  if (!seen.has(key)) seen.set(key, page);
}
let pages = Array.from(seen.values());
const read = pages.length;

// 2. Not the product's own site: a label of its domain that is the product
// name (notion.so, help.notion.so, notion-vip.com). Whole words only, so a
// tool called Box does not remove dropbox.com.
const isOwnSite = (p) => {
  const labels = p.domain.split('.').slice(0, -1);
  const words = labels.join('-').split('-');
  const CUEW = ['alternative', 'alternatives', 'vs', 'versus', 'best', 'top', 'competitor', 'competitors', 'compare', 'comparison', 'review', 'reviews', 'like', 'similar', 'guide', 'list'];
  if (labels.join('').split('-').join('') === req.key) return true;
  return (req.ownLabels || req.tokens).some((t) => words.includes(t)) && !words.some((w) => CUEW.includes(w));
};
pages = pages.filter((p) => {
  if (isOwnSite(p)) { drop(p, "the product's own site"); return false; }
  return true;
});

// 3. A list of alternatives, or a round-up that includes the product, says so
// in its title, or several times in its opening; one stray "replace" in a
// product review does not. The model returns nothing for a page that turns out
// not to be a list, so this only has to keep the obvious non-lists out.
const CUES = ['alternativ', 'competitor', ' versus ', ' vs ', ' vs.', 'similar to', 'instead of', 'replace', 'compared', 'other than', 'rival'];
const TITLE_CUES = CUES.concat(['compar', 'best ', 'top ', ' apps', ' tools', ' software', 'platforms', 'options']);
const nameLower = req.name.toLowerCase();
const cueScore = (p) => {
  const head = (p.title + ' ' + p.text.slice(0, 3000)).toLowerCase();
  let score = 0;
  for (const c of CUES) score += head.split(c).length - 1;
  const title = ' ' + p.title.toLowerCase() + ' ';
  return TITLE_CUES.some((c) => title.includes(c)) ? score + 3 : (score >= 3 ? score : 0);
};
pages = pages.filter((p) => {
  const all = (p.title + ' ' + p.text).toLowerCase();
  const mentionsProduct = all.includes(nameLower) || req.tokens.some((t) => all.includes(t));
  p.score = cueScore(p);
  if (!mentionsProduct || p.score === 0) { drop(p, 'it does not look like a list of alternatives to this product'); return false; }
  return true;
});

// 4. One page per site: the one that reads most like a list of alternatives.
const byDomain = new Map();
for (const p of pages) {
  const best = byDomain.get(p.domain);
  if (!best || p.score > best.score || (p.score === best.score && p.text.length > best.text.length)) {
    if (best) drop(best, 'another page of the same site was used');
    byDomain.set(p.domain, p);
  } else {
    drop(p, 'another page of the same site was used');
  }
}
pages = Array.from(byDomain.values()).sort((a, b) => b.score - a.score || a.domain.localeCompare(b.domain));

// The model reads a fixed budget of text, shared by the sources, so a long list
// is read as far down as the budget allows: 40,000 characters each for up to
// six sources, less for seven or eight.
const chosen = pages.slice(0, 8);
const share = Math.min(40000, Math.floor(240000 / Math.max(chosen.length, 1)));
const sources = chosen.map((p, i) => ({
  id: 'S' + (i + 1), title: p.title, url: p.url, host: p.host, domain: p.domain, published: p.published, cut: p.truncated || p.text.length > share, text: p.text.slice(0, share),
}));
for (const p of pages.slice(8)) drop(p, 'only eight sources are used per run');

let problem = '';
if (blocked) problem = 'DuckDuckGo blocked this search, so nothing could be read. Wait several minutes and try again; a block can last longer.';
else if (failure && found === 0) problem = 'The DuckDuckGo search failed: ' + String(failure.error).slice(0, 200) + '. Try again in a few minutes.';
else if (sources.length === 0) problem = 'No page that lists alternatives to ' + req.name + ' could be read.';

const nonce = Math.random().toString(36).slice(2, 10);
const evidence = sources.map((s) => [
  '<<<SOURCE ' + s.id + ' ' + nonce + '>>>',
  'Title: ' + s.title.replace(/\s+/g, ' ').split('<<<').join('<<').split('>>>').join('>>'),
  'Site: ' + s.host,
  'Text:',
  s.text.split('<<<').join('<<').split('>>>').join('>>'),
  '<<<END ' + s.id + ' ' + nonce + '>>>',
].join('\n')).join('\n\n');

return [{ json: {
  ok: !problem, problem, blocked, searchFailed: !!failure && found === 0, name: req.name, kind: req.kind, key: req.key, tokens: req.tokens, ownLabels: req.ownLabels, today: req.today,
  sources, evidence, dropped, counts: { found, read },
} }];

// A name is shown only if code can confirm what the model said about it: the
// quote is in the source it names (spacing and typographic variants aside), the
// name stands in that quote as a whole word with the source's own capitalisation,
// the sentence offers that tool, and the tool is not the product itself. The
// table then shows that passage as the page spells it, finished to the end of its sentence.
// Each name is then counted by the number of different sites that carry it.
// No site votes twice, and a site does not vote for a tool that is its own: a
// vendor's "alternatives to Notion" page that lists the vendor's own product is
// advertising, not a second opinion.
const bundle = $('Choose the sources').first().json;
const input = $input.first().json;
const output = input.output;

// The model call can fail (credential, rate limit, an answer that is not the
// list asked for). Say so, instead of reporting that nothing was found.
if (input.error || !output || !Array.isArray(output.alternatives)) {
  return [{ json: { failed: true, reason: String(input.error || 'its answer could not be read as a list').slice(0, 200), rows: [], rejected: 0, selfVotes: 0, proposed: 0, listed: 0 } }];
}
const proposed = output.alternatives;

const alnum = (s) => String(s).toLowerCase().split('+').join('plus').split('#').join('sharp').split('').filter((c) => (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')).join('');
const isLower = (c) => !!c && c === c.toLowerCase() && c !== c.toUpperCase();
const isUpper = (c) => !!c && c === c.toUpperCase() && c !== c.toLowerCase();
const isDigit = (c) => !!c && c >= '0' && c <= '9';
const isWordChar = (c) => isDigit(c) || isLower(c) || isUpper(c);

// Text with spacing and typographic quotes taken out, and where each kept
// character was. Extraction can glue words together ("databasesCoda"), and a
// model may re-space a sentence or swap a curly quote for a straight one;
// neither should make a real quote fail. Letters keep their case, so the
// sentence still has to be the page's own.
const fold = (c) => {
  if (/[\s\u00AD\u200B-\u200F\u2060-\u2064\u202A-\u202E\u2066-\u2069]/.test(c)) return '';
  if ("‘’‛′ʼ\u0060´".includes(c)) return "'";
  if ('“”‟″«»„'.includes(c)) return '"';
  if (/[\u2010-\u2015\u2212\uFE58\uFE63\uFF0D]/.test(c)) return '-';
  return c.normalize('NFKD').replace(/[\u0300-\u036f]/g, '');
};
// A model often marks a cut with an ellipsis at either end; one in the middle would hide words.
const trimEllipsis = (s) => {
  let t = s.trim();
  while (t.startsWith('…') || t.startsWith('...')) t = t.slice(t.startsWith('…') ? 1 : 3).trim();
  while (t.endsWith('…') || t.endsWith('...')) t = t.slice(0, t.endsWith('…') ? -1 : -3).trim();
  return t;
};
const squash = (s) => {
  let text = '';
  const map = [];
  for (let i = 0; i < s.length; i++) {
    const f = fold(s[i]);
    for (let k = 0; k < f.length; k++) { text += f[k]; map.push(i); }
  }
  return { text, map };
};

// The name stands alone: "Notion" is not in "Notional". A change from lower
// case to a capital counts as a break, because glued text has no spaces.
const wholeWordAt = (text, name, from, to) => {
  const startsUpper = isUpper(name.charAt(0));
  const last = name.charAt(name.length - 1);
  const endsLow = isLower(last) || isDigit(last);
  for (let at = text.indexOf(name, from); at !== -1; at = text.indexOf(name, at + 1)) {
    if (to !== undefined && at + name.length > to) return -1;
    const before = text.charAt(at - 1);
    const after = text.charAt(at + name.length);
    const beforeOk = !isWordChar(before) || (startsUpper && (isLower(before) || isDigit(before)));
    const afterOk = !isWordChar(after) || (isUpper(after) && endsLow);
    if (beforeOk && afterOk) return at;
  }
  return -1;
};
const countWholeWord = (text, name) => {
  let n = 0;
  let from = 0;
  while (n < 2) {
    const at = wholeWordAt(text, name, from);
    if (at === -1) break;
    n += 1;
    from = at + name.length;
  }
  return n;
};

const STOP = ['free', 'best', 'top', 'pricing', 'price', 'prices', 'plans', 'features', 'alternative', 'alternatives', 'software', 'app', 'apps', 'tool', 'tools', 'platform',
  'review', 'reviews', 'comparison', 'overview', 'conclusion', 'introduction', 'faq', 'pros', 'cons', 'cost', 'summary', 'other', 'others', 'more', 'here', 'open source', 'ai'];
// Words that make two names one tool: "Notion AI" and "Notion", "Microsoft
// OneNote" and "OneNote", "monday.com" and "monday".
const VENDOR = ['microsoft', 'google', 'apple', 'adobe', 'amazon', 'zoho', 'atlassian', 'salesforce', 'oracle', 'ibm', 'meta', 'sap', 'aws'];
const TRAILING = ['com', 'io', 'app', 'ai', 'software', 'inc', 'hq'];
const coreWords = (name) => {
  let w = name.split(/[\s.]+/).map(alnum).filter(Boolean);
  while (w.length > 1 && TRAILING.includes(w[w.length - 1])) w = w.slice(0, -1);
  return w;
};
const sameTool = (a, b) => {
  if (!a.length || !b.length) return false;
  const [s, l] = a.length <= b.length ? [a, b] : [b, a];
  const same = (x, y) => x.join(' ') === y.join(' ');
  if (same(s, l)) return true;
  if (same(l.slice(0, s.length), s) && l.slice(s.length).every((w) => /^[0-9]+$/.test(w))) return true;
  return l.length === s.length + 1 && VENDOR.includes(l[0]) && same(l.slice(1), s);
};

// A tool whose name is the domain of the site that lists it is that site's own.
const SECOND = ['co', 'com', 'org', 'net', 'ac', 'gov', 'edu', 'or', 'ne', 'go'];
const isOwnTool = (domain, name) => {
  const dkey = alnum(domain.split('.').slice(0, -1).filter((l) => !SECOND.includes(l)).join(''));
  if (dkey.length < 3) return false;
  const core = alnum(name.split(/[\s.]+/).filter((w, i, all) => !(i > 0 && TRAILING.includes(alnum(w)))).join(''));
  const words = name.split(/[\s.]+/).map(alnum).filter(Boolean);
  // The domain is the tool's name (any.do), starts or ends with it (usecarly.com, get-alfred.ai), or is the name's first word (zoho.com for Zoho Projects).
  return dkey === core || words[0] === dkey || words.filter((w) => w.length >= 4).includes(dkey) || (dkey.length >= 4 && core.startsWith(dkey)) || (core.length >= 5 && dkey.includes(core));
};

const byId = new Map(bundle.sources.map((s) => [s.id, s]));
const squashed = new Map();
let rejected = 0;
let selfVotes = 0;
const candidates = [];

for (const c of proposed) {
  // The model sometimes copies the marker's per-run code after the id ("S1 k3j9x2"); the id is the first word.
  const idMatch = String((c && c.source_id) || '').trim().match(/^\W*(?:source\s*)?s?\s*0*([0-9]+)/i);
  const source = idMatch ? byId.get('S' + idMatch[1]) : undefined;
  const name = String((c && c.name) || '').trim();
  const quote = trimEllipsis(String((c && c.quote) || ''));
  const key = alnum(name) || name.toLowerCase().split(/\s+/).join('');
  const quoteWords = quote.split(/\s+/).filter(Boolean).length;
  const isProduct = key === bundle.key || sameTool(coreWords(name), coreWords(bundle.name)) || name.split(/[\s.]+/).map(alnum).some((w) => w && bundle.tokens.includes(w));
  if (!source || !key || name.length < 2 || name.length > 40 || name.split(/\s+/).filter(Boolean).length > 5 || STOP.includes(name.toLowerCase()) || isProduct || quoteWords < 5 || quoteWords > 60) { rejected += 1; continue; }
  if (!squashed.has(source.id)) squashed.set(source.id, squash(source.text));
  const sq = squashed.get(source.id);
  const q = squash(quote).text;
  const at = q.length >= 20 ? sq.text.indexOf(q) : -1;
  if (at === -1) { rejected += 1; continue; }
  // The quoted passage as the source spells it, so the name is checked with the source's capitalisation.
  const segFrom = sq.map[at];
  const segTo = sq.map[at + q.length - 1] + 1;
  const found = wholeWordAt(source.text, name, segFrom, segTo);
  const pos = found === -1 ? -1 : found - segFrom;
  // Show the passage as the page spells it, finished to the end of its sentence when the model stopped short: a half sentence can say the opposite of the whole.
  let shown = source.text.slice(segFrom, segTo).trim();
  if (!/[.!?]["'’”)\]]*$/.test(shown)) {
    const limit = Math.min(source.text.length, segTo + 200);
    for (let i = segTo; i < limit; i++) {
      const ch = source.text.charAt(i);
      if (ch === '\n') { shown = source.text.slice(segFrom, i).trim(); break; }
      if ('.!?'.includes(ch) && (i + 1 >= source.text.length || /\s/.test(source.text.charAt(i + 1)))) { shown = source.text.slice(segFrom, i + 1).trim(); break; }
    }
  }
  // A tool named only to be compared against or avoided ("Unlike X, ...", "better than X") is not being offered; the words before it count even when the quote begins at the name.
  const leadIn = found === -1 ? '' : source.text.slice(Math.max(0, found - 24), found).toLowerCase();
  if (/\b(unlike|than|instead of|rather than|avoid|except|without|beyond|compared (to|with)|versus|vs\.?|not|never|skip|over)[\s"'(]*$/.test(leadIn)) { rejected += 1; continue; }
  // A name that appears once in a page may be a common word or a passing mention; a listed tool is named again.
  if (pos === -1 || countWholeWord(source.text, name) < 2) { rejected += 1; continue; }
  candidates.push({ source, name, key, quote: shown, qkey: source.id + '|' + q, pos });
}

// One sentence supports one tool: when it names several, it belongs to the one it starts with.
const first = new Map();
for (const c of candidates) {
  const best = first.get(c.qkey);
  if (!best || c.pos < best.pos) first.set(c.qkey, c);
}
const entries = [];
const perSource = new Map();
for (const c of candidates) {
  if (first.get(c.qkey) !== c) { rejected += 1; continue; }
  if (isOwnTool(c.source.domain, c.name)) { selfVotes += 1; continue; }
  const used = perSource.get(c.source.id) || 0;
  if (used >= 25 && !entries.some((e) => e.key === c.key && e.sources.has(c.source.id))) { rejected += 1; continue; }
  let e = entries.find((x) => x.key === c.key);
  if (!e) { e = { key: c.key, name: c.name, words: coreWords(c.name), quote: c.quote, quoteSource: c.source.id, sources: new Set() }; entries.push(e); }
  if (!e.sources.has(c.source.id)) perSource.set(c.source.id, used + 1);
  // The first source (the one that reads most like a list) supplies the quote.
  if (Number(c.source.id.slice(1)) < Number(e.quoteSource.slice(1))) { e.quote = c.quote; e.quoteSource = c.source.id; }
  e.sources.add(c.source.id);
}

// Merge names that are one tool, keeping the shorter name, which every longer form contains.
entries.sort((a, b) => a.name.length - b.name.length);
const merged = [];
for (const e of entries) {
  const into = merged.find((m) => sameTool(m.words, e.words));
  if (!into) { merged.push(e); continue; }
  for (const s of e.sources) into.sources.add(s);
  if (Number(e.quoteSource.slice(1)) < Number(into.quoteSource.slice(1))) { into.quote = e.quote; into.quoteSource = e.quoteSource; }
}

const listed = new Set();
for (const m of merged) for (const s of m.sources) listed.add(s);
const allTools = merged.length;
const manyTools = merged.filter((m) => m.sources.size >= 2).length;
const rows = merged
  .map((e) => ({ name: e.name, quote: e.quote, quoteSource: e.quoteSource, sourceIds: Array.from(e.sources).sort((a, b) => Number(a.slice(1)) - Number(b.slice(1))), votes: e.sources.size }))
  .sort((a, b) => b.votes - a.votes || a.name.localeCompare(b.name))
  .slice(0, 15);

return [{ json: { failed: false, rows, rejected, selfVotes, proposed: proposed.length, listed: listed.size, allTools, manyTools } }];

// The result table, built here as HTML from data. Nothing written by a source
// page or the model is rendered as markup: every string is escaped, and the
// only links are source addresses that start with http(s).
const bundle = $('Choose the sources').first().json;
const result = $input.first().json;
const rows = result.rows || [];
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const byId = new Map(bundle.sources.map((s) => [s.id, s]));
const link = (s) => (String(s.url).toLowerCase().startsWith('https://') || String(s.url).toLowerCase().startsWith('http://')
  ? '<a href="' + esc(s.url) + '" target="_blank" rel="noopener noreferrer nofollow">' + esc(s.host) + '</a>'
  : esc(s.host));
const read = bundle.sources.length;
const plural = (n, one, many) => n + ' ' + (n === 1 ? one : many);
const foot = '<p class="foot">Each run makes one DuckDuckGo search, and DuckDuckGo limits searches per IP address, so leave a few minutes between runs.</p>';

let html = '<h1>Alternatives to ' + esc(bundle.name) + (bundle.kind ? ' (' + esc(bundle.kind) + ')' : '') + '</h1>';

if (result.failed) {
  html += '<p class="lead">The pages were collected, but the AI model did not return a usable list: ' + esc(result.reason) + '.</p>' +
    '<p>Check the credential on the model node, or try again in a minute.</p>' + foot;
  return [{ json: { html } }];
}

// A tool is counted over the sites whose list this run could confirm, not over every page the model was given.
const listed = result.listed || 0;
const table = (list, startAt) => '<table><thead><tr><th>#</th><th>Alternative</th><th>Named by</th><th>What a source says</th></tr></thead><tbody>' +
  list.map((r, i) => {
    const sites = r.sourceIds.map((id) => link(byId.get(id))).join(', ');
    const quoteSite = byId.get(r.quoteSource);
    return '<tr><td>' + (startAt + i + 1) + '</td><td><b>' + esc(r.name) + '</b></td>' +
      '<td>' + r.votes + ' of ' + plural(listed, 'site', 'sites') + '<p class="meta">' + sites + '</p></td>' +
      '<td><blockquote>' + esc(r.quote) + '</blockquote><p class="meta">' + link(quoteSite) + '</p></td></tr>';
  }).join('') + '</tbody></table>';

const several = rows.filter((r) => r.votes >= 2);
const single = rows.filter((r) => r.votes < 2);
const anyCut = bundle.sources.some((s) => s.cut);

if (!rows.length) {
  html += '<p class="lead">Checked ' + esc(bundle.today) + '. ' + plural(read, 'page was', 'pages were') + ' used, but no alternative could be confirmed: ' +
    (result.proposed === 0
      ? 'the model found no alternatives in them.'
      : 'none of the names the model proposed could be found, with its quoted sentence, on the page it named.') + '</p>' +
    '<p>Try again, or add what kind of product it is, for example &ldquo;note-taking app&rdquo;.</p>';
} else {
  html += '<p class="lead">Checked ' + esc(bundle.today) + '. ' + plural(read, 'page was', 'pages were') + ' used; ' + plural(listed, 'site gave', 'separate sites gave') + ' a list of alternatives to ' + esc(bundle.name) + ' that could be confirmed. ' +
    '<b>' + (result.manyTools == null ? several.length : result.manyTools) + '</b> tool' + ((result.manyTools == null ? several.length : result.manyTools) === 1 ? ' is' : 's are') + ' named by two or more of them' + (result.allTools > rows.length ? '; the table shows the first ' + rows.length + ' of ' + result.allTools + ' tools found' : ', <b>' + single.length + '</b> by one site only') + '. ' +
    'The count is how many separate sites list a tool, not how good it is: sites that earn commission from lists can favour some tools, and two sites can copy each other. Each sentence is copied from the page it names.</p>';
  if (listed === 1) {
    html += '<p class="warn">Only one site&rsquo;s list could be confirmed, so this is that site&rsquo;s opinion, not agreement between sites.</p>';
  } else if (listed === 2) {
    html += '<p class="warn">Only two sites&rsquo; lists could be confirmed, so a tool named by both is a small sample, not a consensus.</p>';
  }
  if (anyCut) html += '<p class="meta">Pages longer than ' + Math.max.apply(null, bundle.sources.filter((s) => s.cut).map((s) => s.text.length)) + ' characters were read only up to there, so a tool far down a long list can be missed.</p>';
  if (several.length) html += '<h2>Named by several sites</h2>' + table(several, 0);
  if (single.length) html += '<h2>Named by one site only</h2><p class="meta">Treat these with care: one site is one opinion.</p>' + table(single, several.length);
}
html += '<details><summary>The ' + plural(read, 'page', 'pages') + ' used</summary><ul>' +
  bundle.sources.map((s) => '<li>' + link(s) + ' &mdash; ' + esc(s.title) + '</li>').join('') + '</ul></details>';
const dropped = bundle.dropped || [];
if (dropped.length) {
  html += '<details><summary>' + plural(dropped.length, 'page', 'pages') + ' left out</summary><ul>' +
    dropped.map((d) => '<li>' + esc(d.host) + ' <em>(' + esc(d.reason) + ')</em></li>').join('') + '</ul></details>';
}
if (result.selfVotes) {
  html += '<p class="foot">' + plural(result.selfVotes, 'mention', 'mentions') + ' of a tool on that tool&rsquo;s own website ' + (result.selfVotes === 1 ? 'was' : 'were') + ' not counted.</p>';
}
if (result.rejected) {
  html += '<p class="foot">' + result.rejected + ' of ' + result.proposed + ' names the model proposed were left out: the quoted sentence was not on the page it named, the name did not stand in it as a whole word, appeared only once on the page, was the product itself, or the sentence was about another tool or named it only to compare it or warn against it, or the name or quote was not usable.</p>';
}
html += foot;

return [{ json: { html } }];

// One page for every way a run can end without a table: the product name was
// not accepted, DuckDuckGo blocked the search, or no list page could be read.
// Each says what happened and what to try.
const input = $input.first().json;
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

const dropped = input.dropped || [];
const heading = input.sources ? 'No sources to compare' : 'Nothing to search for';
let html = '<h1>' + esc(heading) + '</h1><p>' + esc(input.problem || 'The request could not be completed.') + '</p>';
if (input.sources) {
  const counts = input.counts || { found: 0, read: 0 };
  const plural = (n, one, many) => n + ' ' + (n === 1 ? one : many);
  html += '<p>' + plural(counts.found, 'search result was', 'search results were') + ' found and ' + plural(counts.read, 'page', 'pages') + ' could be read.</p>';
  if (dropped.length) {
    html += '<details open><summary>' + dropped.length + ' page' + (dropped.length === 1 ? '' : 's') + ' left out</summary><ul>' +
      dropped.map((d) => '<li>' + esc(d.host) + ' <em>(' + esc(d.reason) + ')</em></li>').join('') + '</ul></details>';
  }
  if (!input.blocked && !input.searchFailed) html += '<p>Try again with the product&rsquo;s exact name, or add what kind of product it is, for example &ldquo;project management tool&rdquo;.</p>';
}
html += '<p class="foot">Each run makes one DuckDuckGo search, and DuckDuckGo limits searches per IP address, so leave a few minutes between runs.</p>';
return [{ json: { html } }];
